// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.datastore;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public class HashFileBloomFilterTest {

	@TempDir
	File tempDir;

	@Test
	public void minimumIntegerHashWorksAcrossClearAndReopen() throws IOException {
		File hashFilePath = new File(tempDir, "values.hash");
		int[] hashes = { Integer.MIN_VALUE, Integer.MIN_VALUE + 1, -1, 0, 1, Integer.MAX_VALUE };

		try (HashFile hashFile = new HashFile(hashFilePath, false, 16)) {
			for (int hash : hashes) {
				assertThat(findIds(hashFile, hash)).as("IDs for hash %s before storing", hash).isEmpty();
			}

			for (int i = 0; i < hashes.length; i++) {
				hashFile.storeID(hashes[i], i + 1);
			}
			hashFile.storeID(Integer.MIN_VALUE, hashes.length + 1);

			for (int i = 0; i < hashes.length; i++) {
				if (hashes[i] == Integer.MIN_VALUE) {
					assertThat(findIds(hashFile, hashes[i])).containsExactly(i + 1, hashes.length + 1);
				} else {
					assertThat(findIds(hashFile, hashes[i])).containsExactly(i + 1);
				}
			}

			hashFile.clear();
			for (int hash : hashes) {
				assertThat(findIds(hashFile, hash)).as("IDs for hash %s after clear", hash).isEmpty();
			}
			hashFile.storeID(Integer.MIN_VALUE, 99);
		}

		try (HashFile reopened = new HashFile(hashFilePath, false, 16)) {
			assertThat(findIds(reopened, Integer.MIN_VALUE)).containsExactly(99);
			assertThat(findIds(reopened, Integer.MIN_VALUE + 1)).isEmpty();
			reopened.storeID(Integer.MIN_VALUE + 1, 100);
			assertThat(findIds(reopened, Integer.MIN_VALUE + 1)).containsExactly(100);
		}
	}

	@Test
	public void zeroHashSkipsEmptySlotsWithAndWithoutBloomFilter() throws IOException {
		File bloomFilePath = new File(tempDir, "bloom-zero.hash");
		try (HashFile hashFile = new HashFile(bloomFilePath, false, 16)) {
			hashFile.storeID(0, 10);
			assertThat(findIds(hashFile, 0)).containsExactly(10);
		}

		File reopenedFilePath = new File(tempDir, "reopened-zero.hash");
		try (HashFile hashFile = new HashFile(reopenedFilePath, false, 16)) {
			hashFile.storeID(1, 11);
		}

		try (HashFile reopened = new HashFile(reopenedFilePath, false, 16)) {
			assertThat(findIds(reopened, 0)).isEmpty();
			reopened.storeID(0, 12);
			assertThat(findIds(reopened, 0)).containsExactly(12);
		}
	}

	private static List<Integer> findIds(HashFile hashFile, int hash) throws IOException {
		List<Integer> ids = new ArrayList<>();
		HashFile.IDIterator iterator = hashFile.getIDIterator(hash);
		try {
			int id;
			while ((id = iterator.next()) >= 0) {
				ids.add(id);
			}
		} finally {
			iterator.close();
		}
		return ids;
	}
}
